  var model = core.make({"id":"pmb","kind":"drill","level":"mbbs","review":"ai_drafted","timeLimitSec":600,"title":{"en":"Postmenopausal bleeding drill: when to refer","hi":"रजोनिवृत्ति के बाद रक्तस्राव ड्रिल: कब refer करें"},"scenario":{"en":"Three women after the menopause, each with unexplained vaginal bleeding. Work through the referral decision for each one in turn. Teaching scenario, not real patients.","hi":"रजोनिवृत्ति के बाद की तीन महिलाएँ, हर एक को बिना कारण की योनि से रक्तस्राव है। हर एक के लिए refer करने का फ़ैसला एक के बाद एक करें। यह शिक्षण परिदृश्य है, असली मरीज़ नहीं।"},"sources":[{"label":"NICE NG12 Suspected cancer: recognition and referral, Endometrial cancer, recommendations 1.5.12 and 1.5.14","url":"https://www.nice.org.uk/guidance/ng12/chapter/recommendations-organised-by-site-of-cancer"}],"stages":[{"id":"older","src":0,"timeSec":60,"prompt":{"en":"Woman 1: aged 58, unexplained bleeding after the menopause, not on hormone therapy. What do you do?","hi":"पहली महिला: 58 वर्ष, रजोनिवृत्ति के बाद बिना कारण का रक्तस्राव, कोई hormone therapy नहीं। आप क्या करेंगे?"},"options":[{"id":"a","correct":true,"critical":true,"next":"younger","text":{"en":"Refer on the suspected cancer pathway for endometrial cancer.","hi":"endometrial cancer के लिए suspected cancer pathway पर refer करें।"},"feedback":{"en":"NICE 1.5.12: refer on the suspected cancer pathway for endometrial cancer if aged 55 and over with unexplained post-menopausal bleeding that cannot be attributed to HRT.","hi":"NICE 1.5.12: 55 वर्ष या अधिक उम्र में बिना कारण का रजोनिवृत्ति के बाद रक्तस्राव, जो HRT से न समझा जा सके, तो endometrial cancer के लिए suspected cancer pathway पर refer करें।"}},{"id":"b","correct":false,"next":"younger","text":{"en":"Reassure her. Bleeding after the menopause is common.","hi":"उसे आश्वस्त करें। रजोनिवृत्ति के बाद रक्तस्राव आम है।"},"feedback":{"en":"NICE 1.5.12 calls for referral in this group, so reassurance alone is not the recommended step.","hi":"NICE 1.5.12 इस समूह को refer करने को कहता है, इसलिए सिर्फ़ आश्वासन सही कदम नहीं है।"}},{"id":"c","correct":false,"next":"younger","text":{"en":"Review in six months without any investigation.","hi":"छह महीने बाद दोबारा देखें, बिना किसी जाँच के।"},"feedback":{"en":"NICE 1.5.12 calls for referral for women aged 55 and over with this bleeding, not a wait.","hi":"NICE 1.5.12 55 वर्ष या अधिक उम्र की ऐसी महिलाओं को refer करने को कहता है, इंतज़ार करने को नहीं।"}}]},{"id":"younger","src":0,"timeSec":60,"prompt":{"en":"Woman 2: aged 48, unexplained bleeding after the menopause, not attributable to HRT. What do you do?","hi":"दूसरी महिला: 48 वर्ष, रजोनिवृत्ति के बाद बिना कारण का रक्तस्राव, जो HRT से नहीं समझा जा सकता। आप क्या करेंगे?"},"options":[{"id":"a","correct":true,"critical":true,"next":"hrt","text":{"en":"Consider a suspected cancer pathway referral for endometrial cancer.","hi":"endometrial cancer के लिए suspected cancer pathway पर refer करने पर विचार करें।"},"feedback":{"en":"NICE 1.5.14: consider a suspected cancer pathway referral for women aged under 55 with unexplained post-menopausal bleeding that cannot be attributed to HRT.","hi":"NICE 1.5.14: 55 वर्ष से कम उम्र में बिना कारण का रजोनिवृत्ति के बाद रक्तस्राव, जो HRT से न समझा जा सके, तो refer करने पर विचार करें।"}},{"id":"b","correct":false,"next":"hrt","text":{"en":"No referral, because she is under 55.","hi":"कोई referral नहीं, क्योंकि उम्र 55 से कम है।"},"feedback":{"en":"NICE 1.5.14 says to consider referral for under-55s with this bleeding. Being under 55 does not remove the need to think about it.","hi":"NICE 1.5.14 55 से कम उम्र की ऐसी महिलाओं में referral पर विचार करने को कहता है। 55 से कम उम्र होने से इस पर सोचना नहीं हट जाता।"}},{"id":"c","correct":false,"next":"hrt","text":{"en":"Refer only if she is over 55.","hi":"सिर्फ़ 55 से ऊपर होने पर refer करें।"},"feedback":{"en":"The direct referral rule in 1.5.12 is for 55 and over. For under-55s, NICE 1.5.14 says to consider referral.","hi":"1.5.12 का सीधा referral नियम 55 और उससे ऊपर के लिए है। 55 से कम के लिए NICE 1.5.14 referral पर विचार करने को कहता है।"}}]},{"id":"hrt","src":0,"timeSec":60,"prompt":{"en":"Woman 3: aged 58, bleeding after the menopause while on hormone therapy. What must you establish before you decide on referral?","hi":"तीसरी महिला: 58 वर्ष, hormone therapy पर है और रजोनिवृत्ति के बाद रक्तस्राव है। refer करने से पहले क्या तय करना ज़रूरी है?"},"options":[{"id":"a","correct":true,"critical":true,"next":"end","text":{"en":"Whether the bleeding can be attributed to the HRT. If it cannot, refer on the suspected cancer pathway.","hi":"क्या रक्तस्राव HRT से समझा जा सकता है। अगर नहीं, तो suspected cancer pathway पर refer करें।"},"feedback":{"en":"NICE 1.5.12 includes the condition that the bleeding cannot be attributed to HRT, so the HRT history decides whether this pathway applies.","hi":"NICE 1.5.12 की शर्त है कि रक्तस्राव HRT से न समझा जा सके, इसलिए HRT का इतिहास तय करता है कि यह रास्ता लागू होगा या नहीं।"}},{"id":"b","correct":false,"next":"end","text":{"en":"That the bleeding is harmless, because she is on HRT.","hi":"कि रक्तस्राव हानिरहित है, क्योंकि वह HRT पर है।"},"feedback":{"en":"NICE 1.5.12 ties the referral to whether the bleeding can be attributed to HRT. Being on HRT does not settle that on its own.","hi":"NICE 1.5.12 referral को इस पर जोड़ता है कि रक्तस्राव HRT से समझा जा सकता है या नहीं। सिर्फ़ HRT पर होना इसे अपने-आप तय नहीं करता।"}},{"id":"c","correct":false,"next":"end","text":{"en":"Nothing. Age 58 is enough, and the HRT is irrelevant.","hi":"कुछ नहीं। 58 वर्ष की उम्र काफ़ी है, और HRT का कोई महत्व नहीं।"},"feedback":{"en":"NICE 1.5.12 includes the condition 'cannot be attributed to HRT', so the HRT history is relevant to the decision.","hi":"NICE 1.5.12 में शर्त है 'HRT से न समझा जा सके', इसलिए फ़ैसले में HRT का इतिहास मायने रखता है।"}}]}]});
